// Initializes newly activated rooms across all 5 acts. For each act with dirty rooms (bRoomDirty flag), iterates all active rooms and populates uninitialized rooms (eFlags & 1 == 0) with wandering monsters, preset units, inactive units, objects, and room monsters. Also reinitializes inactive units for already-initialized rooms if not yet processed. Clears bRoomDirty flag after processing each act. Critical for dynamic content spawning as players explore.
static void InitNewRooms(::SGAMEDATA * pGame) {
    D2RoomStrc* pRoomLoop;
    int32_t nErrorLine;
    D2DrlgActStrc* pAct;
    if (!pGame) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0xc60);
      exit(-1);
    }

    D2DrlgActStrc** ppActLoop = pGame->pAct;
    int nActRemaining = 5;
    do {
      pAct = *ppActLoop;
      if (pAct && pAct->bRoomDirty) {
        for (pRoomLoop = D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomFromAct(pAct); pRoomLoop; pRoomLoop = pRoomLoop->pDrlgRoomNext) {
          Monsters::Spawn::MONSTER_TrySpawnWanderingMonster(pGame, pRoomLoop);
          if (!(pRoomLoop->eFlags & 1)) {
            UNIT::SUnit::SUNIT_SpawnPresetUnitsForRoom(pGame, pRoomLoop);
            UNIT::SUnitInactive::SUNITINACTIVE_RoomInit(pGame, pRoomLoop);
            Objects::OBJECT_PopulateRoomObjects(pGame, pRoomLoop);
            Monsters::Spawn::MONSTER_SpawnRoomMonsters(pGame, pRoomLoop);
            pRoomLoop->eFlags |= 1;
            D2Common::DUNGEON::Dungeon::DRLGROOM_SetUnitInactiveProcessed(pRoomLoop, 1);
          } else {
            nErrorLine = D2Common::DUNGEON::Dungeon::DRLGROOM_IsUnitInactiveProcessed(pRoomLoop);
            if (!nErrorLine) {
              UNIT::SUnitInactive::SUNITINACTIVE_RoomInit(pGame, pRoomLoop);
              D2Common::DUNGEON::Dungeon::DRLGROOM_SetUnitInactiveProcessed(pRoomLoop, 1);
            }
          }
        }

        (*ppActLoop)->bRoomDirty = 0;
      }

      ppActLoop++;
      nActRemaining--;
      if (!nActRemaining) {
        return;
      }
    } while (true);
}

// Frees idle rooms across all 5 acts to conserve memory. For each act, iterates active rooms and checks idle tick count via DRLGROOM_GetIdleTicks. Rooms idle for 10+ frames and passing TestRoomCanUntile (no players nearby) are candidates for cleanup. Moves all units in room to inactive lists via SERVER_GAME_UNIT_method, then removes room from act via RemoveRoomFromAct. Called every 12 frames from GAME_ServerGameLoop. Critical for dynamic memory management in large games.
void __stdcall CleanupIdleRooms(::SGAMEDATA * pGame) {
    D2RoomStrc* pRoomNext;
    int32_t nIdleTicks;
    BOOL bCanUntile;
    D2RoomStrc* pRoom;
    D2UnitStrc* pUnit;
    D2UnitStrc* pUnitNext;
    D2DrlgActStrc** ppActLoop = pGame->pAct;
    int nActRemaining = 5;
    do {
      if (*ppActLoop) {
        pRoomNext = D2Common::DUNGEON::Dungeon::DRLGROOM_GetRoomFromAct(*ppActLoop);
        while (true) {
          pRoom = pRoomNext;
          if (!pRoom) {
            break;
          }

          pRoomNext = pRoom->pDrlgRoomNext;
          nIdleTicks = D2Common::DUNGEON::Dungeon::DRLGROOM_GetIdleTicks(pRoom);
          if (nIdleTicks > 10) {
            bCanUntile = D2Common::DUNGEON::Dungeon::DRLGROOM_TestRoomCanUntile(*ppActLoop, pRoom);
            if (bCanUntile) {
              pUnit = pRoom->pUnitList;
              while (pUnit) {
                pUnitNext = pUnit->pRoomNext;
                UNIT::SUnitInactive::SERVER_GAME_UNIT_method(pGame, pUnit);
                pUnit = pUnitNext;
              }

              D2Common::DUNGEON::Dungeon::DRLGROOM_RemoveRoomFromAct(*ppActLoop, pRoom);
            }
          }
        }
      }

      ppActLoop++;
      nActRemaining--;
    } while (nActRemaining);
}

// Frees unused dropped items every 1500 frames (60 seconds at 25 FPS). When dwGameFrame is exact multiple of 0x5dc (1500), iterates all 5 acts and calls FreeUnusedItems + SUNITINACTIVE_FreeUnusedItems for each. Removes items that have been on ground too long or in inactive state. Prevents memory leaks from abandoned loot in long-running games. Returns frame counter / 1500.
void FreeUnusedItems(::SGAMEDATA * pGamee) {
    if (pGamee->dwGameFrame % 0x5dc) {
      return;
    }

    int nActIndex = 0;
    do {
      ITEMS::Items::Drop::FreeUnusedItems(pGamee, nActIndex);
      UNIT::SUnitInactive::SUNITINACTIVE_FreeUnusedItems(pGamee, nActIndex);
      nActIndex++;
    } while (nActIndex < 5);
}

// Checks all clients for connection timeouts. If timeout exceeded and client has file flag 0x4 set with 10+ heartbeat samples and 10+ seconds idle, OR 45+ seconds idle, OR forced timeout flag set, saves that player and disconnects them. Two timeout thresholds: strict (10 seconds with heartbeat monitoring) and lenient (45 seconds absolute). Sets *pnParam if any disconnects occur, triggering full game save. Only active when gnClientTimeoutCheckInterval enabled.
void __stdcall CheckClientTimeouts(::SGAMEDATA * pGame, int * pnParam) {
    // Static local variables (originally global data)
    static uint32_t gnClientTimeoutCheckInterval = 0x1; D2_STATIC_GUARD(gnClientTimeoutCheckInterval, "D2Game::GAME::Server::CheckClientTimeouts::gnClientTimeoutCheckInterval");

    uint32_t dwClientTimeout;
    D2ClientStrc* pClient;
    if (!gnClientTimeoutCheckInterval) {
      return;
    }

    *pnParam = 0;
    DWORD dwCurrentTick = GetTickCount();
    D2ClientStrc* pClientNext = pGame->pClient;
    while (true) {
      uint32_t dwFileFlags;
      pClient = pClientNext;
      if (!pClient) {
        break;
      }

      pClientNext = pClient->pNext;
      dwFileFlags = Clients::CLIENT_TestFileFlags(pClient, 4);
      dwClientTimeout = pClient->dwTimeOut;
      if (dwCurrentTick > dwClientTimeout && (dwFileFlags && dwCurrentTick - dwClientTimeout > 10000 && (uint32_t)pClient->tQServerExt.nHeartbeatSampleCount > 10 || dwCurrentTick - dwClientTimeout > 45000 || pClient->tQServerExt.nForceTimeoutDisconnect) && BattleNetServerService) {
        PLAYER::PlayerSave::SaveGameAllGameTypes(pGame, Clients::CLIENTS_GetControlUnit(pClient, 0), Clients::GetCharName(pClient), 0);
        *pnParam = 1;
        SERVER_DisconnectClient(pGame, pClient, '\0');
      }
    }

    if (!*pnParam) {
      return;
    }

    SaveAllPlayers(pGame);
}

