// Callback invoked when the character-server (CS) delivers save data for a joining client (JOIN step 3). Accumulates chunked save data; on completion with nCsResult==0 stores file-time fields into pClient and sends state-command 2 to advance the join sequence. On CS error or stale pClientContainer, triggers disconnect.
// @sourcefile .\GAME\Game.cpp
uint32_t __stdcall CLIENT_OnDatabaseCharacterReceived(uint32_t nClientId, void * pParam, uint16_t nChunkSize, uint16_t nTotalSize, int32_t nCsResult, uint32_t dwCharFlags, int * pFileTimeData, void * pClientContainer) {
    ::SGAMEDATA* pGame;
    D2ClientStrc* pClient;
    SRVLog(6, "[JOIN 3] %d clientid, %d csresult - Recv\'ed char from CS", nClientId, nCsResult);
    if (nTotalSize) {
      int bAccumulated;
      bAccumulated = Clients::CLIENT_AccumulateSaveData(nClientId, pParam, (uint32_t)nChunkSize, (uint32_t)nTotalSize, (uint32_t)!nCsResult, 1, dwCharFlags);
      if (!bAccumulated) {
        SRVLog(6, "[JOIN]  SrvRecvDatabaseCharacter: Didn\'t recv full char from db - CSResult(%d), ClientID(%d)", nCsResult, nClientId);
        return 1;
      }
    }
    if (nCsResult) {
      SRVLog(6, "[PLAYER LOAD]  ClientAddPlayerToGame()  Error Loading:%s  Error:%d=%s", nCsResult, nClientId);
      QSERVER_ClientDisconnectCallback(nClientId, ".\\GAME\\Game.cpp", 0x407);
    } else {
      if (!nTotalSize) {
        QSERVER_ClientDisconnectCallback(nClientId, ".\\GAME\\Game.cpp", 0x414);
        return 0;
      }

      pGame = NET_SERVER_FindGameByClientId(nClientId);
      if (pGame) {
        pClient = Clients::SERVER_GetClientFromGmeByClientId(pGame, nClientId);
        if (!pClient) {
          Server::Unlock(pGame);
          return 0;
        }
        if (pClient->pClientContainer != pClientContainer) {
          Server::Unlock(pGame);
          QSERVER_ClientDisconnectCallback(nClientId, ".\\GAME\\Game.cpp", 0x479);
          return 0;
        }

        pClient->ftFileTime.dwLowDateTime = *pFileTimeData;
        pClient->ftFileTime.dwHighDateTime = pFileTimeData[1];
        Server::Unlock(pGame);
        SCmd::NET_D2GS_SERVER_SendStateCommand(pClient, 2);
        return (uint32_t)nTotalSize;
      }
    }

    return 0;
}

// GAME_CreateBattleNetGame - Creates BNet multiplayer game. Same subsystem init as SP but with 0x8000 pool size. Registers token on QSERVER, sets game metadata (name/pass/desc/difficulty/expansion/itemformat/seed).
// @sourcefile .\GAME\Game.cpp
uint32_t __stdcall GAME_CreateBattleNetGame(char * szGameName, char * szGamePassword, char * szGameDescription, eD2ArenaFlags flags, uint8_t bTemplate, uint8_t bReserved, uint8_t bLadder, uint16_t * pServerTokenOut) {
    uint32_t nQServerToken;
    if (!gpQServerGameState) {
      return 0;
    }

    *(uint16_t*)(char*)&nQServerToken = QSERVER_GenerateToken();
    TSExportTableSync<::SGAMEDATA, HSGAMEDATA__*, HSGAMEDATALOCK__*, CCritSect, 0>* self = gpQServerGameState;
    if (!(uint16_t)nQServerToken) {
      return 0;
    }

    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(&gpQServerGameState->tSync.m_critsect);
    uint32_t nHashToken = self->GenerateUniqueHandle();
    ::SGAMEDATA* pGame = self->TSHashTable<::SGAMEDATA, HASHKEY_NONE>::New(nHashToken, &self->tKey, 0, 0);
    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&gpQServerGameState->tSync.m_critsect);
    if (!pGame) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x319);
      exit(-1);
    }

    LPCRITICAL_SECTION lpCriticalSection = (LPCRITICAL_SECTION)D2_ALLOC_POOL_AT(nullptr, 0x18, ".\\GAME\\Game.cpp", 0x31c);
    /* LPCRITICAL_SECTION lpCriticalSection for InitializeCriticalSection */ pGame->lpCriticalSection = lpCriticalSection;
    InitializeCriticalSection(lpCriticalSection);
    Fog::Memory::InitializePoolSystem(&pGame->pMemoryPool, szGameName, 0x8000);
    memset(pGame->pUnitList, 0, 0x200);
    memset(pGame->pUnitList + 1, 0, 0x200);
    memset(pGame->pUnitList + 2, 0, 0x200);
    memset(pGame->pUnitList + 3, 0, 0x200);
    memset(pGame->pUnitList + 4, 0, 0x200);
    memset(pGame->fUniqueSpawn, 0, 0x200);
    pGame->nServerToken = (uint16_t)nQServerToken;
    pGame->bGameIsSetup = 1;
    SetGameName(pGame, szGameName, 0);
    Storm::Source::SSTR::SStrCopy(pGame->szGamePassword, szGamePassword, 0x10);
    Storm::Source::SSTR::SStrCopy(pGame->szGameDescription, szGameDescription, 0x20);
    pGame->nTemplateLevel = bTemplate;
    pGame->nReserved = bReserved;
    pGame->nLadder = bLadder;
    if (flags & ARENAFLAG_Expansion) {
      pGame->bExpansion = 1;
    } else {
      pGame->bExpansion = 0;
    }

    pGame->wItemFormat = pGame->bExpansion ? 0x65 : 0x2;
    pGame->eGameType = flags >> 0x15 & GAMETYPE_SINGLEPLAYER_UNCAPPED;
    memset(pGame->anUnitGuidCounters, 0, 6 * sizeof(pGame->anUnitGuidCounters[0]));
    pGame->dwServerGame = 0;
    pGame->pPrev = 0;
    pGame->pNext = 0;
    pGame->dwException = 0;
    pGame->nUberQuestObjectCount = 0;
    pGame->nUberQuestObjectIndex = 0;
    pGame->bUberBaal = 0;
    pGame->bUberDiablo = 0;
    pGame->nDifficulty = (uint8_t)(flags >> 0xc) & 7;
    Server::RollSeed(pGame);
    Event::EVENT_AllocTimerQueue(pGame);
    Arena::AllocArenaControl(pGame, 0, flags, '\0');
    Clients::SetGameDataHook(pGame);
    UNIT::Party::AllocPartyControl(pGame);
    Monster::MonsterRegion::AllocMonsterRegionForGame(pGame);
    uint32_t uVar1 = Objects::ObjectsRgn::AllocObjectControl(pGame);
    pGame->pInitSeed.nSeedHigh = uVar1;
    UNIT::sunitproxy::SUNITPROXY_AllocNpcControl(pGame);
    Quests::QUESTS::AllocQuestControl(pGame);
    QSERVER_PutNewGameOnTokenList((::SGAMEDATA*)nHashToken, (uint16_t)nQServerToken);
    uint32_t nHighResTime = Fog::Src::LogManager::LOGMGR_GetHighResolutionTime();
    pGame->dwLastActivityTime = nHighResTime;
    if (nHighResTime <= 1) {
      pGame->dwLastActivityTime = 2;
    }

    D2TaskNodeStrc* pGameTaskData = D2_NEW_AT(D2TaskNodeStrc, ".\\GAME\\Game.cpp", 0x39a);
    Task::TASK_EnqueueGameTask(pGameTaskData, 0, nHashToken);
    DWORD dwStatsTick = GetTickCount();
    pGame->dwStatsTick = dwStatsTick;
    *pServerTokenOut = pGame->nServerToken;
    return 1;
}

// Already-documented — existing description accurately covers SP/LAN game creation: allocates SGAMEDATA in hash map with generated token, initializes critical section and five unit-type lists, rolls seed, allocates Event/Arena/Party/MonsterRegion/ObjectControl/NpcControl/QuestControl subsystems, creates local D2ClientStrc, sends 0x01 GameFlags and state packets, and enqueues the game-loop task.
// @sourcefile .\GAME\Game.cpp
void __fastcall GAME_CreateSingleplayerGame(int32_t nClientId, char * szGameName, eD2HostGameType neD2HostGameType, eD2PlayerClassID ePlayerClass, char * szCharName, int32_t Unknown4, eD2ArenaFlags eArenaFlags, uint8_t nTemplate, uint8_t Unknown6, uint8_t Unknown7, uint8_t nDifficulty, uint8_t nLanguageCode, uint32_t arg11, uint32_t arg12) {
    TSExportTableSync<::SGAMEDATA, HSGAMEDATA__*, HSGAMEDATALOCK__*, CCritSect, 0>* self = gpQServerGameState;
    if (!gpQServerGameState) {
      return;
    }

    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(&gpQServerGameState->tSync.m_critsect);
    uint32_t dwGameToken = self->GenerateUniqueHandle();
    ::SGAMEDATA* pGame = self->TSHashTable<::SGAMEDATA, HASHKEY_NONE>::New(dwGameToken, &self->tKey, 0, 0);
    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&gpQServerGameState->tSync.m_critsect);
    if (!pGame) {
      return;
    }

    LPCRITICAL_SECTION lpCriticalSection = (LPCRITICAL_SECTION)D2_ALLOC_POOL_AT(nullptr, 0x18, ".\\GAME\\Game.cpp", 0x4d9);
    /* LPCRITICAL_SECTION lpCriticalSection for InitializeCriticalSection */ pGame->lpCriticalSection = lpCriticalSection;
    InitializeCriticalSection(lpCriticalSection);
    pGame->pMemoryPool = 0;
    memset(pGame->pUnitList, 0, 0x200);
    memset(pGame->pUnitList + 1, 0, 0x200);
    memset(pGame->pUnitList + 2, 0, 0x200);
    memset(pGame->pUnitList + 3, 0, 0x200);
    memset(pGame->pUnitList + 4, 0, 0x200);
    memset(pGame->fUniqueSpawn, 0, 0x200);
    pGame->bGameIsSetup = 1;
    uint16_t uVar1 = QSERVER_GenerateToken();
    pGame->nServerToken = uVar1;
    SetGameName(pGame, szGameName, nClientId);
    pGame->nGameType = neD2HostGameType;
    memset(pGame->anUnitGuidCounters, 0, 6 * sizeof(pGame->anUnitGuidCounters[0]));
    pGame->nDifficulty = nDifficulty;
    pGame->nTemplateLevel = nTemplate;
    if (eArenaFlags & ARENAFLAG_Expansion) {
      pGame->bExpansion = 1;
    } else {
      pGame->bExpansion = 0;
    }

    pGame->wItemFormat = pGame->bExpansion ? 0x65 : 0x2;
    pGame->eGameType = eArenaFlags >> 0x15 & GAMETYPE_SINGLEPLAYER_UNCAPPED;
    Server::RollSeed(pGame);
    Event::EVENT_AllocTimerQueue(pGame);
    Arena::AllocArenaControl(pGame, Unknown4, eArenaFlags, nTemplate);
    Clients::SetGameDataHook(pGame);
    D2ClientStrc* pClientCreated = Clients::CreateClient(pGame, nClientId, ePlayerClass, szCharName, "", nullptr, nLanguageCode, arg11, arg12);
    D2Net::Game::Server::AssignClientToToken(nClientId, dwGameToken);
    if (pGame->nGameType == SGAMETYPE_OBNET_HOST) {
      Clients::GAMECLIENT_GetFlags0x20(pClientCreated);
    }

    UNIT::Party::AllocPartyControl(pGame);
    Monster::MonsterRegion::AllocMonsterRegionForGame(pGame);
    uint32_t nObjectSeed = Objects::ObjectsRgn::AllocObjectControl(pGame);
    pGame->pInitSeed.nSeedHigh = nObjectSeed;
    UNIT::sunitproxy::SUNITPROXY_AllocNpcControl(pGame);
    Quests::QUESTS::AllocQuestControl(pGame);
    QSERVER_PutNewGameOnTokenList((::SGAMEDATA*)dwGameToken, pGame->nServerToken);
    SCmd::NET_D2GS_SERVER_Send_0x01_NEWGAME(pClientCreated, 1, pGame);
    SCmd::NET_D2GS_SERVER_SendStateCommand(pClientCreated, 0);
    Clients::CLIENT_SetConnectionState(pClientCreated, 1);
    Clients::CLIENT_SetAct(pClientCreated, (uint8_t)StartingAct);
    uint32_t nHighResTime = Fog::Src::LogManager::LOGMGR_GetHighResolutionTime();
    pGame->dwLastActivityTime = nHighResTime;
    if (nHighResTime <= 1) {
      pGame->dwLastActivityTime = 2;
    }

    D2TaskNodeStrc* pTaskData = D2_NEW_AT(D2TaskNodeStrc, ".\\GAME\\Game.cpp", 0x55b);
    Task::TASK_EnqueueGameTask(pTaskData, 0, dwGameToken);
    if (BattleNetServerService && BattleNetServerService->fpGetDatabaseCharacter) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x562);
      exit(-1);
    }

    SCmd::NET_D2GS_SERVER_SendStateCommand(pClientCreated, 2);
}

void __fastcall SetStat(D2UnitStrc * pUnit, eD2UnitStat eUnitStat, int32_t nValue) {
    if (!pUnit) {
      return;
    }
    if (nValue < 0) {
      D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, eUnitStat, 0, 0);
      return;
    }
    if (pUnit->eUnitType == UNIT_PLAYER) {
      uint32_t nGoldLimit;
      switch (eUnitStat) {
        case UNITSTAT_gold:
          {
            nGoldLimit = D2Common::Units::GetInventoryGoldLimit(pUnit);
            if (nValue > (int)nGoldLimit) {
              D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_gold, 0, 0);
              return;
            }

            break;
          }
        case UNITSTAT_goldbank:
          {
            nGoldLimit = D2Common::Units::GetStashGoldLimit(pUnit);
            if (nValue > (int)nGoldLimit) {
              D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, UNITSTAT_goldbank, 0, 0);
              return;
            }

            break;
          }
      }
    }

    D2Common::Stats::StatsEx::STATLIST_SetUnitStat(pUnit, eUnitStat, nValue, 0);
}

